/* --- vercel --- */
function vercelDeploy(prod,fromGit){const name=(JSON.parse(read('package.json')||'{"name":"app"}').name||'app').replace(/[^a-z0-9-]/g,'-');const host=name+'-'+rnd(9)+'-you.vercel.app';const dep={host,url:'https://'+host,target:prod?'production':'preview',status:'Ready',at:st.clock++,broken:!!st.flags.runtimeBug,body:'<html><title>'+name+'</title> … deployed '+(prod?'to production':'preview')+' …</html>',env:Object.keys(st.vercel.env)};st.vercel.deps.push(dep);if(prod){st.vercel.prevProd=st.vercel.prod;st.vercel.prod=dep;st.vercel.aliasHosts=[name+'.vercel.app'];}return dep}
