   const A=st.aws;const res=[...Object.keys(A.s3).map(b=>'s3://'+b),...Object.values(A.ec2).map(i=>i.id+' ('+i.type+', '+i.state+')'),...Object.values(A.vpcs).map(v=>v.id+' '+v.cidr),...Object.values(A.sgs).map(s=>s.id+' '+s.name+(s.rules.length?' ['+s.rules.map(r=>r.port+' from '+r.cidr).join('; ')+']':'')),...Object.keys(A.users).map(u=>'iam user '+u),...Object.keys(A.lambda).map(f=>'λ '+f),...Object.values(A.rds).map(d=>'rds '+d.id)];if(res.length)parts.push('<div class="eyebrow">AWS resources</div><ul class="mlist">'+res.map(r=>'<li><span class="mono small">'+esc(r)+'</span></li>').join('')+'</ul>');
